USE PersonalFinanceDb;
GO

/*
    Dữ liệu mẫu từ 01/01/2025 đến 01/06/2026 cho PersonalFinanceOffline FINAL.

    Bao gồm:
    - Thu nhập: Lương, Thưởng
    - Chi tiêu: Ăn uống, Đi lại, Mua sắm
    - Tiết kiệm: Tiền mặt, Vàng, Cổ phiếu, Quỹ tiết kiệm

    File này có thể chạy nhiều lần.
    Nó sẽ xóa dữ liệu mẫu cũ có Note bắt đầu bằng [Mẫu 2025-2026] trước khi insert lại.

    Lưu ý:
    - Ngày cuối cùng của dữ liệu mẫu là 01/06/2026, không kéo dài tới 30/06/2026.
    - Khi thêm giao dịch mới sau ngày này sẽ dễ thấy giao dịch mới ở đầu danh sách.
*/

DECLARE @UserId INT;
SELECT @UserId = UserId FROM Users WHERE Username = N'admin';

IF @UserId IS NULL
BEGIN
    RAISERROR(N'Không tìm thấy user admin. Hãy chạy 01_create_database.sql trước.', 16, 1);
    RETURN;
END;

DECLARE @IncomeTypeId INT, @ExpenseTypeId INT, @SavingTypeId INT;
SELECT @IncomeTypeId = TypeId FROM TransactionTypes WHERE TypeCode = 'Income';
SELECT @ExpenseTypeId = TypeId FROM TransactionTypes WHERE TypeCode = 'Expense';
SELECT @SavingTypeId = TypeId FROM TransactionTypes WHERE TypeCode = 'Saving';

IF @IncomeTypeId IS NULL OR @ExpenseTypeId IS NULL OR @SavingTypeId IS NULL
BEGIN
    RAISERROR(N'Thiếu loại Income, Expense hoặc Saving. Hãy kiểm tra TransactionTypes.', 16, 1);
    RETURN;
END;

DECLARE 
    @CatLuong INT,
    @CatThuong INT,
    @CatAnUong INT,
    @CatDiLai INT,
    @CatMuaSam INT,
    @CatTienMat INT,
    @CatVang INT,
    @CatCoPhieu INT,
    @CatQuyTietKiem INT;

SELECT @CatLuong = CategoryId FROM Categories WHERE TypeId = @IncomeTypeId AND CategoryName = N'Lương';
SELECT @CatThuong = CategoryId FROM Categories WHERE TypeId = @IncomeTypeId AND CategoryName = N'Thưởng';

SELECT @CatAnUong = CategoryId FROM Categories WHERE TypeId = @ExpenseTypeId AND CategoryName = N'Ăn uống';
SELECT @CatDiLai = CategoryId FROM Categories WHERE TypeId = @ExpenseTypeId AND CategoryName = N'Đi lại';
SELECT @CatMuaSam = CategoryId FROM Categories WHERE TypeId = @ExpenseTypeId AND CategoryName = N'Mua sắm';

SELECT @CatTienMat = CategoryId FROM Categories WHERE TypeId = @SavingTypeId AND CategoryName = N'Tiền mặt';
SELECT @CatVang = CategoryId FROM Categories WHERE TypeId = @SavingTypeId AND CategoryName = N'Vàng';
SELECT @CatCoPhieu = CategoryId FROM Categories WHERE TypeId = @SavingTypeId AND CategoryName = N'Cổ phiếu';
SELECT @CatQuyTietKiem = CategoryId FROM Categories WHERE TypeId = @SavingTypeId AND CategoryName = N'Quỹ tiết kiệm';

IF @CatLuong IS NULL OR @CatThuong IS NULL
   OR @CatAnUong IS NULL OR @CatDiLai IS NULL OR @CatMuaSam IS NULL
   OR @CatTienMat IS NULL OR @CatVang IS NULL OR @CatCoPhieu IS NULL OR @CatQuyTietKiem IS NULL
BEGIN
    RAISERROR(N'Thiếu danh mục mẫu. Hãy kiểm tra bảng Categories.', 16, 1);
    RETURN;
END;

DELETE FROM Transactions
WHERE UserId = @UserId
  AND Note LIKE N'[Mẫu 2025-2026]%';




/* Kiểm tra kết quả sau import */
SELECT 
    COUNT(*) AS TotalSampleRows,
    MIN(TransactionDate) AS FromDate,
    MAX(TransactionDate) AS ToDate
FROM Transactions
WHERE UserId = @UserId
  AND Note LIKE N'[Mẫu 2025-2026]%';

SELECT 
    CONVERT(varchar(7), tr.TransactionDate, 120) AS MonthKey,
    SUM(CASE WHEN tt.TypeCode = 'Income' THEN tr.Amount ELSE 0 END) AS TotalIncome,
    SUM(CASE WHEN tt.TypeCode = 'Expense' THEN tr.Amount ELSE 0 END) AS TotalExpense,
    SUM(CASE WHEN tt.TypeCode = 'Saving' THEN tr.Amount ELSE 0 END) AS TotalSaving,
    SUM(CASE 
        WHEN tt.TypeCode = 'Income' THEN tr.Amount
        WHEN tt.TypeCode = 'Expense' THEN -tr.Amount
        WHEN tt.TypeCode = 'Saving' THEN -tr.Amount
        ELSE 0
    END) AS AvailableBalance
FROM Transactions tr
INNER JOIN TransactionTypes tt ON tr.TypeId = tt.TypeId
WHERE tr.UserId = @UserId
  AND tr.Note LIKE N'[Mẫu 2025-2026]%'
GROUP BY CONVERT(varchar(7), tr.TransactionDate, 120)
ORDER BY MonthKey;
GO
